<body>
<header><h1><span class="accent">&#9670;</span> Public Service Registration</h1></header>
<main>
<div class="panel">
<h2>Create Account</h2>
<p class="sub">All fields marked with * are required.</p>
<form id="regForm" novalidate autocomplete="on">
<div class="form-grid">
<div>
<label for="username">Username <span class="req">*</span></label>
<input type="text" id="username" name="username" required autocomplete="username" minlength="3" maxlength="30" aria-describedby="usernameErr">
<div class="err" id="usernameErr" role="alert"></div>
</div>
<div>
<label for="email">Email <span class="req">*</span></label>
<input type="email" id="email" name="email" required autocomplete="email" aria-describedby="emailErr">
<div class="err" id="emailErr" role="alert"></div>
</div>
<div>
<label for="dob">Date of Birth</label>
<input type="date" id="dob" name="dob" autocomplete="bday" aria-describedby="dobErr">
<div class="err" id="dobErr" role="alert"></div>
</div>
<div></div>
<div>
<label for="password">Password <span class="req">*</span></label>
<div class="pw-wrap">
<input type="password" id="password" name="new-password" required autocomplete="new-password" minlength="8" aria-describedby="passwordErr">
<button type="button" class="toggle-pw" data-target="password" aria-label="Show password">Show</button>
</div>
<div class="err" id="passwordErr" role="alert"></div>
</div>
<div>
<label for="confirm">Confirm Password <span class="req">*</span></label>
<div class="pw-wrap">
<input type="password" id="confirm" name="confirm-password" required autocomplete="new-password" aria-describedby="confirmErr">
<button type="button" class="toggle-pw" data-target="confirm" aria-label="Show password confirmation">Show</button>
</div>
<div class="err" id="confirmErr" role="alert"></div>
</div>
<div class="full chk-row">
<input type="checkbox" id="tos" name="tos" required aria-describedby="tosErr">
<label for="tos">I accept the <strong>Terms of Service</strong> and <strong>Privacy Policy</strong> <span class="req">*</span></label>
</div>
<div class="full"><div class="err" id="tosErr" role="alert"></div></div>
<div class="full">
<button type="submit" class="submit">Register</button>
<div class="msg" id="formMsg"></div>
</div>
</div>
</form>
</div>
</main>
<script>
(function(){
var KEY='reg_users_v1';
function getUsers(){try{return JSON.parse(localStorage.getItem(KEY))||[];}catch(e){return[];}}
function saveUser(u){var list=getUsers();list.push(u);localStorage.setItem(KEY,JSON.stringify(list));}
function exists(username,email){var list=getUsers();var un=username.toLowerCase(),em=email.toLowerCase();for(var i=0;i<list.length;i++){if(list[i].username===un||list[i].email===em)return list[i];}return null;}
var form=document.getElementById('regForm');
var fields={username:document.getElementById('username'),email:document.getElementById('email'),dob:document.getElementById('dob'),password:document.getElementById('password'),confirm:document.getElementById('confirm'),tos:document.getElementById('tos')};
var errs={username:document.getElementById('usernameErr'),email:document.getElementById('emailErr'),dob:document.getElementById('dobErr'),password:document.getElementById('passwordErr'),confirm:document.getElementById('confirmErr'),tos:document.getElementById('tosErr')};
var msg=document.getElementById('formMsg');
function setErr(name,text){errs[name].textContent=text;fields[name].classList.toggle('invalid',!!text);fields[name].classList.toggle('valid',!text&&fields[name].value.trim()!=='');}
function clearAll(){Object.keys(errs).forEach(function(k){setErr(k,'');});msg.className='msg';msg.textContent='';}
function validateField(name){
var v=fields[name].value;
if(name==='username'){
if(!v.trim()){setErr('username','Username is required.');return false;}
if(v.trim().length<3){setErr('username','Username must be at least 3 characters.');return false;}
if(!/^[a-zA-Z0-9_]+$/.test(v.trim())){setErr('username','Only letters, numbers, and underscores allowed.');return false;}
setErr('username','');return true;
}
if(name==='email'){
if(!v.trim()){setErr('email','Email is required.');return false;}
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())){setErr('email','Enter a valid email address.');return false;}
setErr('email','');return true;
}
if(name==='dob'){
if(v){var d=new Date(v),now=new Date();if(isNaN(d)||d>now){setErr('dob','Enter a valid past date.');return false;}}
setErr('dob','');return true;
}
if(name==='password'){
if(!v){setErr('password','Password is required.');return false;}
if(v.length<8){setErr('password','Password must be at least 8 characters.');return false;}
if(!/[A-Z]/.test(v)||!/[a-z]/.test(v)||!/[0-9]/.test(v)){setErr('password','Include uppercase, lowercase, and a number.');return false;}
setErr('password','');return true;
}
if(name==='confirm'){
if(!v){setErr('confirm','Please confirm your password.');return false;}
if(v!==fields.password.value){setErr('confirm','Passwords do not match.');return false;}
setErr('confirm','');return true;
}
if(name==='tos'){
if(!fields.tos.checked){setErr('tos','You must accept the terms.');return false;}
setErr('tos','');return true;
}
return true;
}
Object.keys(fields).forEach(function(k){
var el=fields[k];
var evt=k==='tos'?'change':'blur';
el.addEventListener(evt,function(){validateField(k);});
if(k!=='tos')el.addEventListener('input',function(){if(el.classList.contains('invalid'))validateField(k);});
});
document.querySelectorAll('.toggle-pw').forEach(function(btn){
btn.addEventListener('click',function(){
var inp=document.getElementById(btn.getAttribute('data-target'));
var show=inp.type==='password';
inp.type=show?'text':'password';
btn.textContent=show?'Hide':'Show';
btn.setAttribute('aria-label',show?'Hide '+btn.getAttribute('aria-label').replace('Show ',''):btn.getAttribute('aria-label').replace('Hide ','Show '));
inp.focus();
});
});
form.addEventListener('submit',function(e){
e.preventDefault();
clearAll();
var valid=true;
['username','email','dob','password','confirm','tos'].forEach(function(k){if(!validateField(k))valid=false;});
if(!valid){var first=form.querySelector('.invalid');if(first)first.focus();return;}
var dup=exists(fields.username.value.trim(),fields.email.value.trim());
if(dup){
var reason=[];
if(dup.username===fields.username.value.trim().toLowerCase())reason.push('username');
if(dup.email===fields.email.value.trim().toLowerCase())reason.push('email');
msg.className='msg error';
msg.textContent='An account with this '+reason.join(' and ')+' already exists.';
msg.style.display='block';
return;
}
saveUser({username:fields.username.value.trim().toLowerCase(),email:fields.email.value.trim().toLowerCase(),dob:fields.dob.value||null,registered:new Date().toISOString()});
msg.className='msg success';
msg.textContent='Registration successful! Welcome, '+fields.username.value.trim()+'.';
msg.style.display='block';
form.reset();
Object.keys(fields).forEach(function(k){fields[k].classList.remove('valid','invalid');});
});
})();
</script>
</body>
</html>
